SELECT EXTRACT(hour FROM TRY_CAST(order_purchase_timestamp AS TIMESTAMP)) AS heure,
       COUNT(*) AS commandes
FROM entrepot.orders GROUP BY 1 ORDER BY commandes DESC;

SELECT CASE WHEN payment_installments > 1 THEN 'plusieurs fois' ELSE 'une fois' END AS modalite,
       ROUND(AVG(payment_value), 2) AS montant_moyen
FROM entrepot.order_payments GROUP BY 1 ORDER BY montant_moyen DESC;

SELECT ROUND(AVG(review_score), 3) AS note_moyenne
FROM entrepot.order_reviews
WHERE review_comment_message ILIKE '%atraso%' OR review_comment_message ILIKE '%atrasad%';
